'use strict';

/**
 * Extracts perimeter points from an array of boxes that form a region
 * @param {Array<{x: number, y: number, width: number, height: number}>} boxes
 * @returns {Array<{x: number, y: number}>} Array of perimeter points in clockwise order
 */
function getPerimeterPoints(boxes) {
    if (!boxes || boxes.length === 0) return [];
    var uniqueLines = new Map();
    let lineKey = (line)=>{
        return `(${line.point1.x},${line.point1.y}),(${line.point2.x},${line.point2.y})`
    }
    let addLine = (line)=>{
        let key = lineKey(line);
        if(uniqueLines.has(key)){
            uniqueLines.get(key).count++;
            return
        }
        uniqueLines.set(key, {line: line, count: 1});
    }
    
    
    console.log(boxes);
    boxes.forEach(box => {
        if (box.height>0 && box.width>0){
                
            //left
            addLine(new VC.LineSegment(new VC.Point(box.x, box.y), new VC.Point(box.x, box.y+box.height)));
            //right
            addLine(new VC.LineSegment(new VC.Point(box.x + box.width, box.y), new VC.Point(box.x + box.width, box.y+box.height)));
            //top
            addLine(new VC.LineSegment(new VC.Point(box.x, box.y), new VC.Point(box.x+box.width, box.y)));
            //bottom
            addLine(new VC.LineSegment(new VC.Point(box.x, box.y+box.height), new VC.Point(box.x+box.width, box.y+box.height)));
        
        }
    });
    
    //remove lines where count>1
    let removableKeys = []
    uniqueLines.forEach((v,k)=>{
        if(v.count>1){
            removableKeys.push(k);
        }
    });
    removableKeys.forEach((k)=>{uniqueLines.delete(k);});

    var ul = new Map(uniqueLines);

    console.log("uniqueLines", ul);

    //reorder line segments
    let perimeterPoints = [];
    while(uniqueLines.size>1){
        if(perimeterPoints.length == 0){
            let firstEntry = uniqueLines.entries().next().value;
            perimeterPoints.push(firstEntry[1].line.point1);
            perimeterPoints.push(firstEntry[1].line.point2);
            uniqueLines.delete(firstEntry[0]);
            continue;
        }
        let lastPoint = perimeterPoints[perimeterPoints.length - 1];
        let nextPoint = null
        let dropKey = ""
        uniqueLines.forEach((v,k)=>{
            if(nextPoint!=null){
                return
            }
            if (v.line.point1.x == lastPoint.x && v.line.point1.y == lastPoint.y){
                nextPoint = v.line.point2;
                dropKey = k;
            } else if (v.line.point2.x == lastPoint.x && v.line.point2.y == lastPoint.y){
                nextPoint = v.line.point1;
                dropKey = k
            }
        })
        if(nextPoint==null){
            console.log(lastPoint)
            console.log(perimeterPoints)
            console.log(uniqueLines)
            if(lastPoint.x == perimeterPoints[0].x && lastPoint.y == perimeterPoints[0].y){
                perimeterPoints.splice(perimeterPoints.length - 1,1);
            }
            break;

        }
        perimeterPoints.push(nextPoint);
        uniqueLines.delete(dropKey);
    }

    //bevel the corners
    let last = null;
    let current = null;
    let next = null;
    let beveledPoints=[];
    for(let p=0; p<perimeterPoints.length + 2; p++){
        last = current;
        current = next;
        next = perimeterPoints[p%perimeterPoints.length];
        if(last==null){
            continue;
        }
        console.log("beveling");
        if(next.x!=last.x && next.y!=last.y){
            //bevel
            let p1 = new VC.Point(
                VC.Math.percentToRange(.292895, current.x, last.x),
                VC.Math.percentToRange(.292895, current.y, last.y)
            )
            let p2 = new VC.Point(
                VC.Math.percentToRange(.292895, current.x, next.x),
                VC.Math.percentToRange(.292895, current.y, next.y)
            )
            beveledPoints.push(p1);
            beveledPoints.push(p2);
        }else{
            beveledPoints.push(current);
        }
    }
    console.log("beveled", beveledPoints);

    jitteredPoints = [];
    for(let b=0 ; b<beveledPoints.length; b++){
        jitteredPoints.push(new VC.Point(
            beveledPoints[b].x + VC.Math.random(-1, 1),
            beveledPoints[b].y + VC.Math.random(-1, 1),
        ));
    }
    
    return beveledPoints;
}

class LavaPool extends GameObject{

    static Factory(room){
        let pools = [];
        let heatTiles = room.heatTiles;//Room.getHeatTiles(room);
        //scan for quick return
        if(!any(heatTiles, (t)=>{return t<=3})){
            return pools;
        }

        //step 1: find "dead" tiles.
        let tiles = [];
        let x = 0;
        let y = 0;
        for(let t=0; t<heatTiles.length; t++){
            if(heatTiles[t]<=3) {
                var tile = new VC.Box(x + Math.round(room.box.x), y+Math.round(room.box.y), 50, 50);//Math.min(50, room.box.width-(x+50)), Math.min(50, room.box.height-(y+50)));
                
                tile.heat = heatTiles[t];
                if(tile.width>0 && tile.height>0 && (!(room instanceof PolygonalRoom) || room.bounds.contains(tile))){
                    tiles.push(tile);
                }
            }
            x+=50;
            if(x>=room.box.width){
                x = 0;
                y+=50;
            }
        }

        //step 2: group into regions. 
        let regions = [];
        let solved = [];
        let rCount = 0;
        for(let t=0; t<tiles.length; t++){
            let tile = tiles[t];
            if(t == 0){
                tile.region = rCount;
                solved.push(tile)
                continue;
            }
            let regionFound = false;
            for(let s=0; s<solved.length; s++){
                let tile2 = solved[s];
                if (
                    (Math.abs(tile2.x + tile2.width - tile.x) < 10 && Math.abs(tile2.y - tile.y)<5) ||
                    (Math.abs(tile2.y + tile2.height - tile.y) < 10 && Math.abs(tile2.x - tile.x)<5) ||
                    (Math.abs(tile.x + tile.width - tile2.x) < 10 && Math.abs(tile2.y - tile.y)<5) ||
                    (Math.abs(tile.y + tile.height - tile2.y) < 10 && Math.abs(tile2.x - tile.x)<5) ||
                    tile.collidesWith(tile2)
                ){
                    tile.region = tile2.region;
                    regionFound = true;
                    solved.push(tile);
                    break;
                }
            }
            if(!regionFound){//new region
                rCount++
                tile.region=rCount;
                solved.push(tile);
            }
        }

        //merge neighboring regions
        let changed = false;
        do {
            changed = false;
            for(let s=0; s<solved.length; s++){
                for(let p=0; p<solved.length; p++){
                    if(s==p){
                        continue;
                    }
                    let t = solved[s];
                    let tile = solved[p];

                    if(tile.region == t.region){
                        continue;
                    }
                    
                    if (
                        (Math.abs(t.x + t.width - tile.x) < 10 && Math.abs(t.y - tile.y)<10) ||
                        (Math.abs(t.y + t.height - tile.y) < 10 && Math.abs(t.x - tile.x)<10) ||
                        (Math.abs(tile.x + tile.width - t.x) < 10 && Math.abs(t.y - tile.y)<10) ||
                        (Math.abs(tile.y + tile.height - t.y) < 10 && Math.abs(t.x - tile.x)<10) ||
                        tile.collidesWith(t)
                    ){
                        changed = true;
                        let region = Math.min(t.region, tile.region);
                        t.region = region;
                        tile.region = region;
                    }
                }
            }
        } while(changed);

        console.log("rCount", rCount);
        console.log("solved", solved);
        //group into regions;
        for(let r = 0; r<rCount+1; r++){
            regions.push([]);
        }
        for(let s=0; s<solved.length; s++){
            let t = solved[s];
            regions[t.region].push(t);
        }
        console.log("regions", regions);

        let polygons = []
        for(let r = 0; r<regions.length; r++){
            //push the points twoards the center if outside the room
            let points = getPerimeterPoints(regions[r])
            let center = room.box.center();
            points.forEach(point=>{
                while(!room.bounds.containsPoint(point)){
                    point.x += point.x<center.x ? 1 : -1;
                    point.y += point.y<center.y ? 1 : -1;
                }
            })
            //eliminate duplicate / close points
            let snapDistance = 14;
            let eliminated = false;
            do {
                eliminated = false;
                let pointsToDelete = [];
                for(let p = 0; p<points.length; p++){
                    let currentPoint = points[p];
                    let nextPoint = points[(p+1) % points.length];
                    if(currentPoint.distanceTo(nextPoint) <= snapDistance){
                        pointsToDelete.push(currentPoint);
                        pointsToDelete.push(nextPoint);
                        eliminated = true;
                    }
                }
                pointsToDelete.forEach((pt)=>{
                    let index = points.indexOf(pt);
                    if(index>-1){
                        points.splice(index,1);
                    }
                })
            } while(eliminated)
            

            polygons.push(new VC.Polygon(points, true));
        
        }

        //finally, push the new pools.
        for(let p=0; p<polygons.length; p++){
            if(polygons[p].area()>500 && regions[p].length>1){
                var pool = new LavaPool(room, polygons[p], regions[p]);
                pools.push(pool);
            }
        }

        return pools;
    }

    sprite = null;
    #bounds = null;
    #polygon = null;

    #region = null;
    constructor(room, polygon, region){
        super(room)
        this.playSound(0,SoundEffects.LAVA_FLOW, .05 , true);
        this.#polygon = polygon;
        this.polygon = polygon;
        this.#region = region;
        this.columnWidth = VC.Math.random(5,9);
        this.plane = Plane.ETHEREAL;
        this.layer = Layer.SHADOW;   
        this.particles = [];
        this.nextParticleGen = Date.now();
        this.bubbles = [];
        this.nextBubbleGen = Date.now();
        this.firstMove = true;
    }

    move(deltaT){
        this.room.objects.filter((o)=>(o.plane==Plane.PHYSICAL && this.#polygon.contains(o.box) && o.hurt && (o.z==null || o.z<=5))).forEach((o)=>{  
            this.playSound(1,SoundEffects.LAVA_SIZZLE,.5,false);
            if (o.health>0){
                let centerRoom = this.room.box.center();
                let oCenter = o.box.center();
                let tan = VC.Trig.tangentFromPoints(centerRoom.x, centerRoom.y, oCenter.x, oCenter.y);
                let angle = Math.atan(tan);

                o.box.x += Math.sin(angle) * 10 * (oCenter.y > centerRoom.y ? -1 : 1)
                o.box.y += Math.cos(angle) * 10 * (oCenter.y > centerRoom.y ? -1 : 1);
                o.hurt(5, null, 0);
            }
        });

        let handbrake = 0;
        while((this.nextBubbleGen<Date.now() || this.bubbles.length<this.#region.length) && handbrake < this.#region.length * 2){
            let tile = this.#region[VC.Math.random(0,this.#region.length-1)]
            if(tile!=null){
                let coords = tile.center();
                coords.x+=VC.Math.random(-18,18);
                coords.y+=VC.Math.random(-15,18);
                if(tile!=null && this.#polygon.containsPoint(coords)){
                    this.bubbles.push({
                        start: Date.now() + VC.Math.random(0,800),
                        center: coords,
                        size: VC.Math.random(1,3)
                    });
                    this.nextBubbleGen=Date.now()+VC.Math.random(50, 800);
                }
            }
            handbrake++;
        }

        handbrake = 0;
        while((this.nextParticleGen<Date.now() || this.particles.length<this.#region.length) && handbrake < this.#region.length * 2){
            let tile = this.#region[VC.Math.random(0,this.#region.length-1)]
            if(tile!=null){
                let coords = tile.center();
                coords.x+=VC.Math.random(-23,23);
                coords.y+=VC.Math.random(-23,23);
                if(tile!=null && this.#polygon.containsPoint(coords)){
                    this.particles.push({
                        kill: Date.now() + 750 * Math.random() + 250,
                        center: coords,
                        size: VC.Math.random(1,3)
                    });
                    this.nextParticleGen=Date.now()+VC.Math.random(50, 800);
                }
            }
            handbrake++;
        }

        this.firstMove = false;
    }

    render(deltaT, screen){

        if(this.pool == null){
            this.pool = screen.drawPoly(this.#polygon.points, "#ff3b11", "#000000", 1);
  
            let dropY = 6 ;
            //find top edges
            let edges = [];

            let bottomedges = [];
            for (let p = 0; p < this.#polygon.points.length; p++) {
                let currentPoint = this.#polygon.points[p];
                let nextPoint = this.#polygon.points[(p + 1) % this.#polygon.points.length];

                // Edge vector
                let dx = nextPoint.x - currentPoint.x;
                let dy = nextPoint.y - currentPoint.y;

                // Outward normal for CW polygons = (dy, -dx)
                let nx = dy;
                let ny = -dx;   

                // Top edge if outward normal points upward
                if (ny > 0) {
                    let e1 = new VC.Point(currentPoint.x, currentPoint.y + dropY);
                    let e2 = new VC.Point(nextPoint.x, nextPoint.y + dropY);
                    if(!this.#polygon.containsPoint(e1) && this.#polygon.containsPoint(e2) ){
                        let r = this.polygon.pointOfIntersection(new VC.LineSegment(e1,e2));
                        if(r!=null){
                            e1 = r;
                        }
                    }
                    if(!this.#polygon.containsPoint(e2) && this.#polygon.containsPoint(e1)){
                        let r = this.#polygon.pointOfIntersection(new VC.LineSegment(e1,e2));
                        if(r!=null){
                            e2 = r;
                        }
                    }
                    if(!this.#polygon.containsPoint(e1)){
                        let r = this.polygon.pointOfIntersection(new VC.LineSegment(new VC.Point(currentPoint.x, currentPoint.y+1),e1));
                        if(r!=null){
                            e1 = r;
                        }
                    }
                    if(!this.#polygon.containsPoint(e2)){
                        let r = this.#polygon.pointOfIntersection(new VC.LineSegment(new VC.Point(nextPoint.x, nextPoint.y+1),e2));
                        if(r!=null){
                            e2 = r;
                        } 
                    }
                    if(!this.room.bounds.containsPoint(e1)){
                        e1 = this.room.bounds.pointOfIntersection(new VC.LineSegment(currentPoint, e1));
                        if (e1 == null){
                            e1 = currentPoint;
                        }
                    }
                    if(!this.room.bounds.containsPoint(e2)){
                        e2 = this.room.bounds.pointOfIntersection(new VC.LineSegment(nextPoint, e2));
                        if(e2 == null){
                            e2 = nextPoint;
                        }
                    }
                    if (e1 != null && e2 !=null){
                        edges.push([currentPoint, e1, e2, nextPoint]);
                    }
                    
                }else if(ny<0){

                }
            }
            
            console.log("edges", edges)
            edges.forEach(edge=>{
                screen.drawPoly(edge, "#505347", "#000000",1);
            });
            this.glow = screen.drawPoly(this.#polygon.points, null, "#ffeeaa", 6);
            this.glow.attr({"opacity": .33});
            screen.onClear(()=>{
                this.pool = null;
                this.glow = null;
            })
        }

        if(this.nextFlicker == null || this.nextFlicker<Date.now()){
            let intensity = VC.Math.random(75,100) * .01;
            this.pool.attr("fill", VC.Color.rgbToHex({
                r: Math.round(VC.Math.percentToRange(intensity, 212, 255)),
                g: Math.round(VC.Math.percentToRange(intensity, 40,59)),
                b: Math.round(VC.Math.percentToRange(intensity, 3,17))
            }));
            this.nextFlicker = Date.now()+VC.Math.random(300,600);
        }

        this.bubbles.forEach((b)=>{
            if(b.circle==null){
                b.circle = screen.circle(b.center.x,b.center.y,2);
                b.circle.attr({"opacity":.75});
            }
            let age = Date.now() - b.start;

            if (age <0){
              b.circle.attr({"opacity":0});   
            }else if(age<200){
                b.circle.attr({
                    "fill": "#ffeeaa",
                    "stroke": "#ffe100",
                    r: b.size,
                    "stroke-width": 1, 
                    "opacity":.75 
                });   
            }else if(age<400){
                b.circle.attr({
                    "fill": "#ffe100",
                    "stroke": "#ff7000",
                    r: b.size+1,
                    "stroke-width": 1,
                    "opacity":.75
                });   
            }else if(age<600){
                b.circle.attr({
                    "fill": "#ff7000",
                    "stroke": "#ff3b11",
                    r: b.size+2,
                    "stroke-width": 1,
                    "opacity":.75
                });   
            }else if(age<800){
                b.circle.attr({
                    "fill": "#ff3b11",
                    "stroke": "#d42803",
                    r: b.size+3,
                    "stroke-width": 1,
                    "opacity":1  
                });   
            }else {
                b.circle.remove();
                b.circle = null;
                this.bubbles.splice(this.bubbles.indexOf(b),1);
            }
        });

        this.particles.forEach((p)=>{
            if(p.rect==null){
                p.rect = screen.drawRect(p.center.x-p.size/2,p.center.y-p.size/2,p.size, p.size, "#ffeeaa", null, 0);
            }
            if(p.kill > Date.now()){
                p.rect.attr({y: p.rect.attr("y")-deltaT/1000 * 33})
            }else {
                p.rect.remove();
                p.rect = null;
                this.particles.splice(this.particles.indexOf(p),1);
            }
        });
    };

    clear(){
        super.clear();
        if(DEBUG){
            this.pool.remove();
        }
        if(this.bubbles){
            this.bubbles.forEach((b)=>{if(b.circle) b.circle.remove();});
        }
        if(this.particles){
            this.particles.forEach((p)=>{if(p.rect) p.rect.remove();});
        }
    }

    remove(){
        super.remove();
        //this.clear();
    }

}
class ForestTemple extends Temple{
    
    #palette = new Palette(
        "#19351A",//clip color
        "#442A01",//floor color
        "#505347"//wall color
    );
    constructor(){
        super();
    }

    get name(){
        return "Vaelmorra"
    }
    
    get description(){
        return "The Forest Temple"
    }

    //read-only properties
    get music(){
        return Music.FOREST;
    }
    
    get palette(){
        return this.#palette;
    }

    themeLevel(level){
        super.themeLevel(level);
        Temple.addTorches(level);
        
        level.rooms.forEach((room, index) => this.themeRoom(room, index, level));

        if (level.number % 5 === 0){
            level.message = this.name;
        }
    }
    
    themeRoom(room, index, level){
        super.themeRoom(room, index);
        if (index !== 0 && !room.exit && level && level.number % 5 != 4 && !room.secret){
            
            var enemyRange = level.number + 1 ;
            if (enemyRange > 3){
                enemyRange = 3;
            }

            let enemies = VC.Math.random(room.spawnDensity-1, room.spawnDensity + 1)
            for(let i=0; i<enemies; i++){   
                switch(VC.Math.random(0,enemyRange)){
                    case 0:
                        if(room.spawn(new CaveSpider(room, new AutoController()))){
                            level.statistics.caveSpidersSpawned++;
                            level.statistics.enemiesSpawned++;
                        }
                        break;
                    case 1:
                        if(room.spawn(new Snake(room, new AutoController()))){
                            level.statistics.snakesSpawned++;
                            level.statistics.enemiesSpawned++;
                        }
                        break;
                    case 2:
                        for(let j = 0; j<VC.Math.random(1,level.number); j++){
                            if(room.spawn(new Rat(room, new AutoController()))){
                                level.statistics.ratsSpawned++;
                                level.statistics.enemiesSpawned++;
                            }
                        }
                        break;                    
                    case 3: 
                        if(room.spawn(new SwordSkeleton(room, new AutoController()))){
                            level.statistics.swordSkeletonsSpawned++;
                            level.statistics.enemiesSpawned++;
                        }
                        break;
                }
            }
            
        }

        //add vines
        let vines = VC.Math.random(room.spawnDensity * 3, room.spawnDensity * 5);
        for(let v = 0; v<vines; v++){
            new Vine(room);
        }
    }
}

class TempleIcon{
    x = 0;
    y = 0;
    name = "";
    description = "";
    image = "";
    unlocked = false;
    sprite = null;
    constructor(n,d,i,x,y,sound,messages){
        this.x = x;
        this.y = y;
        this.image = i;
        this.name = n;
        this.description = d;
        this.sprite = null;
        this.sound = sound;
        this.messages = messages;
    }
}
class LevelSelectScreen extends VC.Scene {
    #mapElement = null;
    #nameElement = null;
    #nameElement2 = null;
    #descElement = null;
    #descElement2 = null;
    #previewSprite = null;
    #progressBar = null;
    #selected = -2;
    readReady = true;
    #loading = false;
    #modalOpened = false;
    #loadStart = null;

    nextAudioChannel=0;
    audioChannels = [
        new VC.AudioChannel(),
        new VC.AudioChannel(),
        new VC.AudioChannel(),
        new VC.AudioChannel(),
        new VC.AudioChannel()
    ];
    get audioChannel(){
        let n=this.nextAudioChannel;
        this.nextAudioChannel = this.nextAudioChannel + 1;
        this.nextAudioChannel = this.nextAudioChannel % this.audioChannels.length;
        return this.audioChannels[n];
    }

    temples =  [
        new TempleIcon("Vaelmorra", "The Forest Temple", Images.FOREST_TEMPLE, 550, 660, SoundEffects.ENV_FOREST, ["Dusting Manos", "Charming Snakes", "Feeding Rats", "Unearthing Skeletons", "Luring Spiders", "Watering Vines", "Sharpening Spikes"]),
        new TempleIcon("Ka'Zuun", "The Volcano Temple", Images.FIRE_TEMPLE, 190, 480, SoundEffects.ENV_VOLCANO, []),
        new TempleIcon("Seryndal", "The Ocean Temple", Images.WATER_TEMPLE, 500, 320, SoundEffects.ENV_OCEAN, []),
        new TempleIcon("Kufuu", "The Desert Temple", Images.DESERT_TEMPLE, 120, 165, SoundEffects.ENV_DESERT, []),
        new TempleIcon("Iskavorn", "The Ice Temple", Images.ICE_TEMPLE, 500, 25, SoundEffects.ENV_BLIZZARD, []),
    ];
    #lines = [];
    constructor(select){
        console.log("lss", select)
        super();
        if(select!=null){
            this.#selected = select;
        }
    }
    preDisplay(){
        game.infoScreen.clear();
        game.playMusic(Music.CHARGE);

        if(this.#selected == -2){
            for(this.#selected = 0; this.#selected < game.slot.levelState.length; this.#selected++){
                if(game.slot.levelState[this.#selected]==2){
                    break;
                }
            }
        }
        for(let t = 0; t<this.temples.length; t++){
            this.temples[t].unlocked = true;
            if(game.slot.levelState[t]==2){
                break;
            }
        }
    }
    preRender(deltaT){
        let beep = false;
        let boop = false;
        let shuffle = false;
        if(game && game.inputController){
            let input = game.inputController.read();
            
            if (this.readReady == false && input.x == 0 && input.y == 0){
                this.readReady = true;
                return;
            }

            if(this.readReady == true && input.a && !this.#loading){
                //startGame
                this.#loading = true;
                this.#loadStart = Date.now();
                if(this.temples[this.#selected].sound != null){
                    this.audioChannel.play(this.temples[this.#selected].sound, .5, false);
                }
                return;
            }

            if(this.#loading){
                if (Date.now()>(this.#loadStart+3000)){
                    this.transitionTo = new NewGameScene(this.#selected * 5);
                }
                return;
            }

            if(this.readReady && (input.x!=0 || input.y!=0)){
                this.readReady = false;
                switch(this.#selected){
                    case 0:
                        if(this.temples[1].unlocked && (input.y < 0)){
                            this.#selected = 1;
                            beep=true;
                        }
                        break;
                    case 1:
                        if(this.temples[0].unlocked && (input.y > 0)){
                            this.#selected = 0;
                            boop = true;
                        }
                        if(this.temples[2].unlocked && (input.y < 0)){
                            this.#selected = 2;
                            boop = false;
                            beep = true;
                        }
                        break;
                    case 2:
                        if((this.temples[3].unlocked && (input.y<0))){
                            this.#selected = 3;
                            beep=true;
                        }else if((this.temples[1].unlocked && input.y>0) ){
                            this.#selected = 1;
                            boop=true;
                        }
                        break;
                    case 3:
                        if((this.temples[4].unlocked && (input.y<0))){
                            this.#selected = 4;
                            beep=true;
                        } else if(this.temples[2].unlocked && (input.y>0)){
                            this.#selected = 2;
                            boop = true;
                        } 
                        break;

                    case 4:
                        if((this.temples[3].unlocked && input.y>0)){
                            this.#selected = 3;
                            boop=true;
                        }
                        break;
                        
                }
            }
        }
        //{"slot":0,"name":"HUGH","statistics":{"levelsCleared":5,"damageDealt":1510,"damageReceived":362,"goldCollected":4700,"keysCollected":6,"keysSpawned":14,"heartsCollected":24,"chestsSpawned":150,"chestsOpened":50,"enemiesKilled":38,"enemiesSpawned":122,"caveSpidersSpawned":41,"caveSpidersKilled":11,"swordSkeletonsSpawned":6,"swordSkeletonsKilled":0,"bossesSpawned":7,"bossesKilled":4,"snakesSpawned":32,"snakesKilled":8,"ratsSpawned":36,"ratsKilled":15,"doorsUnlocked":5,"doorsSpawned":14,"roomsVisited":36,"roomsSpawned":63,"timeSpent":1249120,"tntCollected":28,"tntThrown":0},"sfxVolume":1,"musicVolume":0.15,"hearts":4,"whip":0,"tntBags":1,"levelState":[0,1,1,1,2]}
        if(shuffle){
            this.audioChannel.play(SoundEffects.TNT, .4, false);
        }else if (boop){
            this.audioChannel.play(SoundEffects.KEY_BOOP, .2, false);
        }else if (beep){
            this.audioChannel.play(SoundEffects.KEY_BEEP, .2, false);
        }
    }
    render(deltaT, screen){

        let sepia = "#45392b";
        let parchment = "#ccb696";
        if(this.#mapElement == null){
            this.#mapElement = screen.image(Images.MAP, 0, 0, 910, 910);
        }
        if(this.#nameElement == null){
            this.#nameElement2 = screen.text(13,843, "NAME");
            this.#nameElement2.attr({ "font-size": "48px", "font-family": "monospace", "fill": sepia, "font-weight": "bold", "font-style": "italic", "text-anchor": "start", "stroke": sepia, "stroke-width":1});
        
            this.#nameElement = screen.text(10,840, "NAME");
            this.#nameElement.attr({ "font-size": "48px", "font-family": "monospace", "fill": parchment, "font-weight": "bold", "font-style": "italic", "text-anchor": "start", "stroke": sepia, "stroke-width":1});
        
        }

        if(this.#descElement == null){
            this.#descElement2 = screen.text(12,882, "Desc");
            this.#descElement2.attr({ "font-size": "28px", "font-family": "monospace", "fill": sepia, "font-weight": "bold", "font-style": "italic", "text-anchor": "start", "stroke": sepia, "stroke-width":1});
        
            this.#descElement = screen.text(10,880, "Desc");
            this.#descElement.attr({ "font-size": "28px", "font-family": "monospace", "fill": parchment, "font-weight": "bold", "font-style": "italic", "text-anchor": "start", "stroke": sepia, "stroke-width":1});
        
        }
        
        if (this.#lines.length==0){
            for(let i=0; i<4; i++){
                if(game.slot.levelState[i]==2){
                    break;
                }
                let x1 = this.temples[i].x + 75;
                let y1 = this.temples[i].y + 75;
                let x2 = this.temples[i+1].x + 75;
                let y2 = this.temples[i+1].y + 75;

                let l = screen.drawLine(x1, y1, x2, y2, sepia, 12).attr({"stroke-dasharray":"-."});
                this.#lines.push(l);
            }
        }
        if(!this.#modalOpened){
            this.temples.forEach((t, i)=>{
                if(i==0 || game.slot.levelState[i-1]<2){       
                    if(t.sprite == null ){
                        t.sprite = new VC.Sprite(screen, t.image, 150, 450, 150, 150, t.x, t.y);
                    }   
                    t.sprite.setAnimation(0, i == this.#selected ? 1 : 0);//todo, if selected, then 1
                    t.sprite.render(deltaT);
                    if(i==this.#selected){
                        this.#nameElement.attr({"text":t.name});
                        this.#nameElement2.attr({"text":t.name});
                        this.#descElement.attr({"text":t.description});
                        this.#descElement2.attr({"text":t.description});
                    }
                }
            });
        }
        if(this.#loading){
            if(this.#modalOpened == false){           
                this.#modalOpened = true;
                //render modal

                this.messages = this.temples[this.#selected].messages;
                this.messages.push("Lighting Torches");
                this.messages.push("Hiding Secrets");
                this.messages.push("Stashing Treasure");
                this.messages.push("Transplanting Hearts");
                this.messages.push("Distributing Gold");
                
                //randomize array
                this.messages = this.messages.sort(() => Math.random() - 0.5);

                //overlay
                let overlay = screen.drawRect(0,0,910,910,sepia, "#000", 0, 0,0)
                overlay.attr({"opacity":.75});
                
                //ticket
                let modalbackground = screen.drawRect(76,305,758,304,parchment, sepia, 5, 0 ,0)
                modalbackground.attr({"stroke-dasharray":"- "});

                //image
                this.#previewSprite = new VC.Sprite(screen, this.temples[this.#selected].image, 300, 900, 300, 300, 532, 307);
                this.#previewSprite.setAnimation(0,2);


                let separator = screen.drawLine(532,307,530,607,sepia, 5);
                separator.attr({"stroke-dasharray":"- "});

                let ne = screen.text(106, 350, "Now Entering:");
                ne.attr({ "font-size": "28px", "font-family": "monospace", "fill": sepia, "font-weight": "bold", "font-style": "italic", "text-anchor": "start", "stroke": sepia, "stroke-width":1});
            
                let n = screen.text(106, 400, this.temples[this.#selected].name);
                n.attr({ "font-size": "60px", "font-family": "monospace", "fill": sepia, "font-weight": "bold", "font-style": "italic", "text-anchor": "start", "stroke": sepia, "stroke-width":1});
            
                let d = screen.text(106, 455, this.temples[this.#selected].description);
                d.attr({ "font-size": "28px", "font-family": "monospace", "fill": sepia, "font-weight": "bold", "font-style": "italic", "text-anchor": "start", "stroke": sepia, "stroke-width":1});
            
                this.messageElement = screen.text(106, 525, this.messages.pop() + "...");
                this.messageElement.attr({ "font-size": "22px", "font-family": "monospace", "fill": sepia, "font-weight": "bold", "font-style": "italic", "text-anchor": "start", "stroke": sepia, "stroke-width":1});
                this.nextMessage = Date.now() + VC.Math.random(250,750);
                this.#progressBar = screen.drawLine(106,500,502,500,sepia, 8);
            }
            this.#previewSprite.render(deltaT)
            let val = VC.Math.percentToRange((Date.now()-this.#loadStart)/3000, 106, 502);
            this.#progressBar.attr("path", "M106,500L" + val + ",500");
            
            if(Date.now()>this.nextMessage && this.messages.length > 1){
                this.messageElement.attr({"text": this.messages.pop() + "..."});
                this.nextMessage = Date.now() + VC.Math.random(250,750);
            }
        }
    }
    postRender(deltaT){}
    postDisplay(){
        this.audioChannels.forEach(ac=>ac.dispose());
        this.audioChannels=[];
    }
}

class PolygonalRoom extends VC.Scene {
    
    objects=[]
    #deadObjects = [];

    x = 0;
    y = 0;
    box = null;
    #offsetX = 0;
    #offsetY = 0;
    wallHeight = 0;

    region = 0;
    opened = 1;
    barred = 0;
    mapped = 0; //HACK: Still in use?
    isBossRoom = 0;//HACK: Relevance?

    doors = [];
    #triangles = [];
    #floor = null;
    palette = LevelFactory.getWorldPalette(1);

    #centerPoint = null;
    tileSeed = 0;
    
    structureRendered = false;
    doorsRendered = false;
    audioChannel = new VC.AudioChannel();


    get offsetX(){
        return this.#offsetX
    }


    get offsetY(){
        return this.#offsetY
    }
    

    constructor(x, y, w, h, wallHeightInBricks, floor){
        super();
        this.#floor = floor
        this.x = x; //map address
        this.y = y; //map address
        this.box = new VC.Box(0,0,w?w:0,h?h:0);
        this.wallHeight = constants.brickHeight * (wallHeightInBricks ? wallHeightInBricks : 5);
        this.tileSeed = Math.floor(Math.random()*100);

        if(this.box.width === 0){
            this.box.width = Math.floor(VC.Math.random(constants.roomMinWidthInBricks, constants.roomMaxWidthInBricks)) * constants.brickWidth;
            //this.box.width = constants.roomMaxWidthInBricks * constants.brickWidth 
        }
        
        if(this.box.height === 0){
            this.box.height = Math.floor(VC.Math.random(constants.roomMinHeightInBricks, constants.roomMaxHeightInBricks)) * constants.brickWidth;
            //this.box.height = constants.roomMaxHeightInBricks * constants.brickWidth 
        }

        //center by default
        this.box.x = Math.round((dimensions.width - this.box.width - this.wallHeight*2) / 2) + this.wallHeight;
        this.box.y = Math.round((dimensions.width - this.box.height - this.wallHeight*2) / 2) + this.wallHeight; 

    }

    #volume = 0;
    get volume(){
        return this.#volume;
    }

    set volume(value){
        value = value < 0 ? 0 : (value > 1 ? 1 : value);
        if(this.#volume !== value){
            this.#volume = value;
            this.#checkAudioLevels();
        }
    }
    #pan = 0;
    get pan(){
        return this.#pan;
    }

    set pan(value){
        value = value < -1 ? -1 : (value > 1 ? 1 : value);
        if(this.#pan !== value){
            this.#pan = value;
            this.#checkAudioLevels()
        }
    }
    
    #checkAudioLevels(){
        this.objects.forEach((o)=>o.checkAudioLevels());
    }

    preRender(deltaT){
        this.objects.forEach((o)=>{
            if(o.state !== State.DYING || o.state !== State.DEAD){
                o.move(deltaT);
            }
            if(o.state === State.DEAD ){
                this.#deadObjects.push(o);
            }
        });
        
        let barred = 0;
        this.objects.forEach((o)=>{
            if(o.team === Team.DUNGEON && o.state !== State.DYING && o.state !== State.DEAD){
                barred = 1;
            }
        });

        if(this.barred!==barred && game && game.level && this === game.level.currentRoom ){
            if(barred){
                this.audioChannel.play(SoundEffects.ROOM_BARRED, game.slot.sfxVolume, false);
            }else{
                this.audioChannel.play(SoundEffects.ROOM_OPENED, game.slot.sfxVolume, false);
            }
            this.barred = barred;
            this.doorsRendered = false
        }
    

    }


    render(deltaT, screen){

        if(!this.structureRendered){
            this.renderStructure(screen);
            this.structureRendered = true;
            screen.onClear(()=>{this.structureRendered = false;})
            this.doorsRendered = false;
            //Room.renderHeatTiles(this, screen);
        }
        if(!this.doorsRendered){
            this.doors.forEach((d)=>{d.render(screen);});
            this.doorsRendered = true;
        }
        //Sort List of objects in current room by their y values.
        this.objects.sort((a,b)=>{return a.layer < b.layer ? -1 : a.layer > b.layer ? 1 : a.box.y < b.box.y ? -1 : a.box.y > b.box.y ? 1 : 0;})

        //Render all objects in current room in order.  
        this.objects.forEach((o)=>o.render(deltaT, screen));
    }

    postRender(deltaT){
        this.#deadObjects.forEach((o)=>{
            if(o!==game.player){
                o.remove();
                o.room = null;
            }
        });
        
        this.#deadObjects = [];   
    }

    postDisplay(){
        let removable = [];
        this.objects.forEach((o)=>{
            if(o!==game.player){
                o.remove();
                removable.push(o);
                //o.room = null;
            }
        });
        removable.forEach((o)=>{ o.room = null;})
        removable = [];
        this.audioChannel.dispose();
    }



    finalize(){
        let centerPoint = new VC.Point (this.box.x + this.box.width/2, this.box.y + this.box.height/2);

        let triangle_north = null;
        let triangle_south = null;
        let triangle_west = null;
        let triangle_east = null;

        let wallTriangles = []
        let doorpadding = constants.doorFrameThickness + constants.doorWidth/2 + constants.brickWidth/2;
        this.doors.forEach((door)=>{
            switch(door.wall){
                case Direction.NORTH:
                    if (Math.abs(door.offset) > doorpadding/2){
                        if (door.offset>0){
                            triangle_north = new VC.Triangle(
                                centerPoint,
                                new VC.Point(
                                    this.box.x + (this.box.width/2 + door.offset) + doorpadding,
                                    (this.box.y)
                                ),
                                new VC.Point(
                                    this.box.x + (this.box.width/2) - doorpadding / 2,
                                    (this.box.y)
                                )
                            );
                        }else{
                            triangle_north = new VC.Triangle(
                                centerPoint,
                                new VC.Point(
                                    this.box.x + (this.box.width/2) + doorpadding / 2,
                                    (this.box.y)
                                ),
                                new VC.Point(
                                    this.box.x + (this.box.width/2 + door.offset) - doorpadding,
                                    (this.box.y)
                                )
                            );
                        }
                    } else {
                        triangle_north = new VC.Triangle(
                            centerPoint,
                            new VC.Point(
                                this.box.x + (this.box.width/2 + door.offset) + doorpadding,
                                (this.box.y)
                            ),
                            new VC.Point(
                                this.box.x + (this.box.width/2 + door.offset) - doorpadding,
                                (this.box.y)
                            )
                        );
                    }
                    break;
                case Direction.EAST:
                    if (Math.abs(door.offset) > doorpadding/2){
                        if (door.offset>0){
                            triangle_east = new VC.Triangle(
                                centerPoint,
                                new VC.Point(
                                    this.box.x + this.box.width,
                                    this.box.y + (this.box.height/2 + door.offset) + doorpadding
                                ),
                                new VC.Point(
                                    this.box.x + this.box.width,
                                    this.box.y + (this.box.height/2) - doorpadding /2
                                )
                            );
                        }else{
                            triangle_east = new VC.Triangle(
                                centerPoint,
                                new VC.Point(
                                    this.box.x + this.box.width,
                                    this.box.y + (this.box.height/2) + doorpadding/2
                                ),
                                new VC.Point(
                                    this.box.x + this.box.width,
                                    this.box.y + (this.box.height/2 + door.offset) - doorpadding
                                )
                            );
                        }
                    } else {
                        triangle_east = new VC.Triangle(
                            centerPoint,
                            new VC.Point(
                                this.box.x + this.box.width,
                                this.box.y + (this.box.height/2 + door.offset) + doorpadding
                            ),
                            new VC.Point(
                                this.box.x + this.box.width,
                                this.box.y + (this.box.height/2 + door.offset) - doorpadding
                            )
                        );
                    }

                    break;
                case Direction.SOUTH:
                    if (Math.abs(door.offset) > doorpadding/2){
                        if (door.offset>0){
                            triangle_south = new VC.Triangle(
                                centerPoint,
                                new VC.Point(
                                    this.box.x + (this.box.width/2 - door.offset) - doorpadding,
                                    (this.box.y + this.box.height)
                                ),
                                new VC.Point(
                                    this.box.x + (this.box.width/2 ) + doorpadding / 2,
                                    (this.box.y + this.box.height)
                                )
                            );
                        }else{
                            triangle_south = new VC.Triangle(
                                centerPoint,
                                new VC.Point(
                                    this.box.x + (this.box.width/2 ) - doorpadding / 2,
                                    (this.box.y + this.box.height)
                                ),
                                new VC.Point(
                                    this.box.x + (this.box.width/2 - door.offset) + doorpadding,
                                    (this.box.y + this.box.height)
                                )
                            );
                        }
                    } else { 
                        triangle_south = new VC.Triangle(
                            centerPoint,
                            new VC.Point(
                                this.box.x + (this.box.width/2 - door.offset) - doorpadding,
                                (this.box.y + this.box.height)
                            ),
                            new VC.Point(
                                this.box.x + (this.box.width/2 - door.offset) + doorpadding,
                                (this.box.y + this.box.height)
                            )
                        );
                    }
                    break;
                case Direction.WEST:
                    if (Math.abs(door.offset) > doorpadding/2){
                        if (door.offset>0){
                            triangle_west = new VC.Triangle(
                                centerPoint,
                                new VC.Point(
                                    this.box.x,
                                    this.box.y + (this.box.height/2 - door.offset) - doorpadding
                                ),
                                new VC.Point(
                                    this.box.x,
                                    this.box.y + (this.box.height/2 ) + doorpadding / 2
                                )
                            );
                        }else{
                            triangle_west = new VC.Triangle(
                                centerPoint,
                                new VC.Point(
                                    this.box.x,
                                    this.box.y + (this.box.height/2) - doorpadding / 2
                                ),
                                new VC.Point(
                                    this.box.x,
                                    this.box.y + (this.box.height/2 - door.offset) + doorpadding
                                )
                            );
                        }
                    } else { 
                        triangle_west = new VC.Triangle(
                            centerPoint,
                            new VC.Point(
                                this.box.x,
                                this.box.y + (this.box.height/2 - door.offset) - doorpadding 
                            ),
                            new VC.Point(
                                this.box.x,
                                this.box.y + (this.box.height/2 - door.offset) + doorpadding 
                            )
                        );
                    }

                    break;
            }
        })

        wallTriangles.push(triangle_east==null ? new VC.Triangle(centerPoint, new VC.Point(this.box.x + this.box.width, this.box.center().y + constants.brickWidth * 1.5), new VC.Point(this.box.x + this.box.width, this.box.center().y - + constants.brickWidth * 1.5)): triangle_east)
        wallTriangles.push(triangle_north==null ? new VC.Triangle(centerPoint, new VC.Point(this.box.center().x + constants.brickWidth * 1.5, this.box.y), new VC.Point(this.box.center().x - constants.brickWidth * 1.5, this.box.y)): triangle_north)
        wallTriangles.push(triangle_west==null ? new VC.Triangle(centerPoint, new VC.Point(this.box.x, this.box.center().y - constants.brickWidth * 1.5), new VC.Point(this.box.x, this.box.center().y + constants.brickWidth * 1.5)): triangle_west)
        wallTriangles.push(triangle_south==null ? new VC.Triangle(centerPoint, new VC.Point(this.box.center().x - constants.brickWidth * 1.5, this.box.y + this.box.height), new VC.Point(this.box.center().x + constants.brickWidth * 1.5, this.box.y + this.box.height)): triangle_south)

        //determine what to do with each corner
        for(let corner = 0; corner < 4; corner ++){
            let method = VC.Math.random(0,2)
         

            let w1 = wallTriangles[corner];
            let w2 = wallTriangles[(corner+1)%4]

            let w1Distance = 0
            let w2Distance = 0
            let distance = 0
            let p4 = null;

            switch (method){
                case 0://corner;
                    //find intersection point.
                    switch(corner){
                        case 0://ne
                        case 2://sw
                            w1.p3.y = w2.p2.y;
                            w2.p2.x = w1.p3.x;
                            break;
                        case 1://nw
                        case 3://se
                            w1.p3.x = w2.p2.x;
                            w2.p2.y = w1.p3.y;
                            break;
                    }
                    break;
                case 1://hallway
                    switch(corner){
                        case 0://ne
                        case 2://sw
                            p4 = new VC.Point(w2.p2.x, w1.p3.y)
                            this.#triangles.push(new VC.Triangle(centerPoint, w1.p3, p4));
                            this.#triangles.push(new VC.Triangle(centerPoint, p4, w2.p2));
                            break;
                        case 1://nw
                        case 3://se
                            p4 = new VC.Point(w1.p3.x, w2.p2.y)
                            this.#triangles.push(new VC.Triangle(centerPoint, w1.p3, p4));
                            this.#triangles.push(new VC.Triangle(centerPoint, p4, w2.p2));
                            break;
                    }
                    break;
                case 2://angle
                    switch(corner){
                        case 0://ne
                            //adjust points
                            w1Distance = w1.p3.y - this.box.y;
                            w2Distance = (this.box.x + this.box.width) - w2.p2.x;
                            distance = Math.min(w1Distance, w2Distance);
                            w1.p3.y = this.box.y + distance;
                            w2.p2.x = this.box.x + this.box.width - distance;
                            this.#triangles.push(new VC.Triangle(centerPoint, w1.p3, w2.p2));
                            break;
                        case 1://nw
                            //adjust points
                            w1Distance = w1.p3.x - this.box.x;
                            w2Distance = w2.p2.y - this.box.y;  
                            distance = Math.min(w1Distance, w2Distance);
                            w1.p3.x = this.box.x + distance;
                            w2.p2.y = this.box.y + distance;
                            this.#triangles.push(new VC.Triangle(centerPoint, w1.p3, w2.p2));
                            break;
                        case 2://sw
                            //adjust points
                            w1Distance = (this.box.y + this.box.height) - w1.p3.y;
                            w2Distance = w2.p2.x - this.box.x; 
                            distance = Math.min(w1Distance, w2Distance);
                            w1.p3.y = this.box.y + this.box.height - distance;
                            w2.p2.x = this.box.x + distance;
                            this.#triangles.push(new VC.Triangle(centerPoint, w1.p3, w2.p2));
                            break;
                        case 3://se
                            
                            w1Distance = (this.box.x + this.box.width) - w1.p3.x;
                            w2Distance = (this.box.y + this.box.height) - w2.p2.y;
                            distance = Math.min(w1Distance, w2Distance);
                            w1.p3.x = this.box.x + this.box.width - distance;
                            w2.p2.y = this.box.y + this.box.height - distance;
                            this.#triangles.push(new VC.Triangle(centerPoint, w1.p3, w2.p2));
                            break;
                            

                    }

            }
        }

        wallTriangles.forEach((w)=>{this.#triangles.push(w);});

        this.#centerPoint = centerPoint;

        let points = [];
        this.#triangles.forEach(t=>{
            points.push(t.p2);
            points.push(t.p3);
        });

        //let uniquePoints = Array.from(new Map(points.map(p => [`${p.x},${p.y}`, p])).values());
  
        this.bounds = new VC.Polygon(points);

        let roomArea = this.bounds.area();

        let maxNumberOfObjects = Math.round((roomArea-constants.minArea) / constants.thresholds)
        let minNumberOfObjects = Math.round(maxNumberOfObjects/2) < 1 ? 1 : Math.round(maxNumberOfObjects/2)
        this.spawnDensity = VC.Math.random(minNumberOfObjects, maxNumberOfObjects);

    }

    angleForPoint(p){
        //case Quadrant 1
        if(p.x>this.#centerPoint.x && p.y>this.#centerPoint.y){
            return VC.Trig.degreesToRadians(45);
        }else if(p.x<this.#centerPoint.x && p.y>this.#centerPoint.y){
            return VC.Trig.degreesToRadians(315);    
        }else if(p.x<this.#centerPoint.x && p.y<this.#centerPoint.y){
            return VC.Trig.degreesToRadians(225);    
        }else if(p.x>this.#centerPoint.x && p.y<this.#centerPoint.y){
            return VC.Trig.degreesToRadians(135);    
        }
    }
  
    intersect(x1, y1, x2, y2, x3, y3, x4, y4) {

        // Calculate the direction of the lines
        let denom = (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1);
        if (denom === 0) {
            return null; // Lines are parallel
        }

        let ua = ((x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)) / denom;
        let ub = ((x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3)) / denom;

        // Calculate the intersection point
        let x = x1 + ua * (x2 - x1);
        let y = y1 + ua * (y2 - y1);
        
        return {x:x, y:y}
    }

    renderStructure(screen){
        //render clip area
            
        //screen.drawRect(0, 0, dimensions.width, dimensions.width, this.palette.clipColor, this.palette.clipColor, 0);
        let clipString = "0 0 " + dimensions.width + " " + dimensions.width
 

        //render floor
        this.#floor.render(screen, this.bounds, this.palette.floorColor);

        
        //render walls
        this.#triangles.forEach((t)=>{
            //project along line.
            let point1 = t.p2;
            let distance = Math.sqrt (Math.pow(this.wallHeight,2) + Math.pow(this.wallHeight,2));
            let angle1 = this.angleForPoint(t.p2);
            let point2 = new VC.Point(Math.sin(angle1) * distance + t.p2.x, Math.cos(angle1) * distance + t.p2.y);
            let angle2 = this.angleForPoint(t.p3);
            let point3 = new VC.Point(Math.sin(angle2) * distance + t.p3.x, Math.cos(angle2) * distance + t.p3.y);
            let point4 = t.p3;
            screen.drawQuad(point1.x, point1.y, point2.x, point2.y, point3.x, point3.y, point4.x, point4.y, 0,0,this.palette.wallColor, "#000", 0);
            
            //draw border
            let borderThickness = Math.sqrt(Math.pow(constants.brickWidth/2, 2) + Math.pow(constants.brickWidth/2,2));
            
            
            screen.drawQuad(
                point2.x, point2.y, 
                Math.sin(angle1) * borderThickness + point2.x, Math.cos(angle1) * borderThickness + point2.y, 
                Math.sin(angle2) * borderThickness + point3.x, Math.cos(angle2) * borderThickness + point3.y, 
                point3.x, point3.y,
                0,0,
                this.palette.clipColor, this.palette.clipColor, 0).attr("clip-rect", clipString);
            
            screen.drawLine(point1.x, point1.y, point2.x, point2.y, "#000", 1.5).attr({opacity:.5});
            screen.drawLine(point3.x, point3.y, point4.x, point4.y, "#000", 1.5).attr({opacity:.5});

            let brickHeight = Math.sqrt (Math.pow(constants.brickHeight,2) + Math.pow(constants.brickHeight,2));

            let rows = this.wallHeight / constants.brickHeight;

            let columns = VC.Trig.distance(t.p2.x, t.p2.y, t.p3.x, t.p3.y) / (constants.brickWidth/2);
            
            for(let c = 0; c<columns; c++){
                let brickPoint1 = new VC.Point(Math.sin(angle1) + t.p2.x, Math.cos(angle1) + t.p2.y);
                let brickPoint2 = new VC.Point(Math.sin(angle2) + t.p3.x, Math.cos(angle2)  + t.p3.y);
                
                let distance = VC.Trig.distance(brickPoint1.x, brickPoint1.y, brickPoint2.x, brickPoint2.y);
                
                let columnDistance = (constants.brickWidth/2) * c
                let mx = brickPoint1.x - (columnDistance * (brickPoint1.x-brickPoint2.x))/distance
                let my = brickPoint1.y - (columnDistance *(brickPoint1.y-brickPoint2.y))/distance
                
                let mortarPoint1 = new VC.Point(mx, my);
                let lastBrickPoint1 = null;
                let lastBrickPoint2 = null; 
            

                for(let r = 0; r<=rows; r++){
                    let i = r * brickHeight;
                    let brickPoint1 = new VC.Point(Math.sin(angle1) * i + t.p2.x, Math.cos(angle1) * i + t.p2.y);
                    let brickPoint2 = new VC.Point(Math.sin(angle2) * i + t.p3.x, Math.cos(angle2) * i + t.p3.y);
                    

                    if(c === 0 && r>0 && r<rows){
                        if(r === 3){
                            if(this.region!==0 || this.palette.regionColor){
                                screen.drawQuad(
                                    lastBrickPoint1.x, lastBrickPoint1.y,
                                    brickPoint1.x, brickPoint1.y,
                                    brickPoint2.x, brickPoint2.y,
                                    lastBrickPoint2.x, lastBrickPoint2.y,
                                    0,0,
                                    this.palette.regionColor ? this.palette.regionColor : regionColor(this.region),
                                    "#000", 
                                    0
                                );
                            }                
                        }
    
                        screen.drawLine(brickPoint1.x, brickPoint1.y, brickPoint2.x, brickPoint2.y, "#000", 1.5).attr({opacity:.5});
                    }
                    let angle3=angle2;
                    if (angle2<angle1){
                        angle3 = angle2 + 2 * Math.PI
                    }

          

                    let mortarAngle = VC.Math.percentToRange(columnDistance/distance,angle1,angle3);

                    let mortarPoint2 = new VC.Point(Math.sin(mortarAngle) * brickHeight + mortarPoint1.x, Math.cos(mortarAngle) * brickHeight + mortarPoint1.y)
                    
                    //tweak mortarPoint2
                    let intersection = this.intersect(mortarPoint1.x, mortarPoint1.y, mortarPoint2.x, mortarPoint2.y, brickPoint1.x, brickPoint1.y, brickPoint2.x, brickPoint2.y);
                    if (intersection){
                        mortarPoint2.x = intersection.x;
                        mortarPoint2.y = intersection.y;
                    }
                    
                    if(r > 0 && (r + c) % 2 === 0){
                        screen.drawLine(mortarPoint1.x, mortarPoint1.y, mortarPoint2.x, mortarPoint2.y, "#000", 1.5).attr({opacity:.5});
                    }
                    mortarPoint1 = mortarPoint2;
                    lastBrickPoint1 = brickPoint1;
                    lastBrickPoint2 = brickPoint2;

                }
                //mortarPoint1.render(screen);
            }

        });


        //this.box.render(screen, "#FF0");

        //this.#triangles.forEach((t)=>t.render(screen, "#00F"))

        //this.bounds.render(screen, "#F00");
   
    }

    
    findDoor(wall){
        for(let i = 0; i<this.doors.length;i++){
            if(this.doors[i].wall === wall){
                return this.doors[i];
            }
        }
        return null;
    }

    boxInside(box){
        let passedPoints = 0;
        let points = [
            new VC.Point(box.x, box.y),
            new VC.Point(box.x + box.width, box.y),
            new VC.Point(box.x + box.width, box.y + box.height),
            new VC.Point(box.x, box.y + box.height),
            
        ]
        points.forEach((p)=>{
            if(any(this.#triangles, (t)=>t.contains(p))){
                passedPoints++;
            }   
        })
        if(passedPoints<4){
            return false;
        }
        return true;    
    }
    
    constrain(gameObject, x2, y2){
        return Room.constrain(this, gameObject, x2, y2);
    }
    
    spawn(object){
        return Room.spawn(this, object);
    }

}


let game

VC.Client.OnReady(()=>{
    game = new Game();

    game.screen.canvas.addEventListener("touchstart",function(e){
        VC.Client._orientation = VC.Orientation.PORTRAIT;
        changeOrientation();
    });
    changeOrientation();
    
    
    document.addEventListener("visibilitychange", () => {
        if (document.hidden) {
            pause();
        }
    }); 
    
    game.debug = DEBUG;
    game.play();
})

window.onbeforeunload = function(){
    if(game && game.level && game.level.statistics && game.slot){
        game.slot.statistics.add(game.level.statistics);
        game.slot.save();
    }
};

window.onerror = function(message, source, lineNumber, colno, error) {
    if(!game.debug){
            
        let body = encodeURI(`
        Send this email to help debug the issue!
        
        Message: ${message}
        
        Error: ${error}

        LineNumber: ${lineNumber}, ${colno}

        Call Stack:
        ${error.stack.replaceAll("https://goldruin.com/play/", "")}

        `);

        let uri = `mailto:Gold Ruin Developers<goldruindev@gmail.com>?subject=GoldRuin ${VERSION} Exception&body=${body}`

        if(confirm("Exception Found!\n\nWould you like to send this error to the developers?")){
            window.open(uri, "_self");
        }

    }
};
